html,body { background:#0f172a !important; margin:0; padding:0; }
.app { height: calc(var(--appsmith-ui-height) * 1px); width: calc(var(--appsmith-ui-width) * 1px); box-sizing: border-box; }
.ag-theme-alpine { --ag-header-background-color: #0f172a; --ag-header-foreground-color: #FFFFFF; --ag-odd-row-background-color: #0f172a; --ag-background-color: #1E293B; --ag-row-hover-color: #26344b; --ag-selected-row-background-color: #26344b; --ag-foreground-color: #e2e8f0; --ag-border-color: #1E293B; --ag-font-family: 'Open Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; --ag-font-size: 14px; --ag-row-height: 46px; --ag-header-height: 50px; --ag-checkbox-checked-color:#3b82f6; --ag-checkbox-unchecked-color:#64748b; border-radius: 6px; border: 1px solid #1E293B; overflow: hidden; height: calc(var(--appsmith-ui-height) * 1px - 4px); }
.ag-theme-alpine .ag-row-odd { background-color: #0f172a !important; }
.ag-theme-alpine .ag-row-even { background-color: #1E293B !important; }
.ag-theme-alpine .ag-row { cursor: pointer; }
.ag-theme-alpine .ag-row-hover { background-color: #26344b !important; }
.ag-theme-alpine .ag-cell { border-right: 1px solid rgba(255,255,255,0.04); display:flex; align-items:center; }
.ag-theme-alpine .ag-header { font-weight: 700; background: #0f172a; border-bottom: 2px solid #1E293B; }
.ag-theme-alpine .ag-header-cell { border-right: 1px solid rgba(255,255,255,0.06); }
.ag-theme-alpine .ag-header-cell-text { color: #FFFFFF; font-weight:700; font-size:15px; }
.ag-theme-alpine .ag-paging-panel { background: #0f172a; color: #FFFFFF; border-top: 2px solid #1E293B; }
.ag-theme-alpine .ag-paging-panel * { color: #FFFFFF !important; }
.ag-theme-alpine .ag-paging-panel .ag-picker-field-wrapper { background: #1E293B; border-color: #1E293B; color: #FFFFFF; }
.ag-theme-alpine .ag-paging-button { color: #FFFFFF !important; opacity: 0.85; }
.ag-theme-alpine .ag-paging-button:hover { opacity: 1; background: #1E293B; border-radius: 4px; }
.ag-theme-alpine .ag-paging-button[disabled] { opacity: 0.4; }
.ag-menu, .ag-menu-option, .ag-tooltip { z-index: 999999 !important; }
::-webkit-scrollbar { width: 10px; height: 10px; background: #0f172a; }
::-webkit-scrollbar-track { background: #0f172a; }
::-webkit-scrollbar-thumb { background: #1E293B; border-radius: 4px; border: 2px solid #0f172a; }
::-webkit-scrollbar-thumb:hover { background: rgba(255,255,255,0.15); }
* { scrollbar-color: #1E293B #0f172a; scrollbar-width: thin; }

